import type { Redis } from "ioredis";
import { TranscodeJob, TranscodeService } from "./transcode";
import { Logger } from "./logger";

export interface QueueMessage<T> {
  id: string;
  body: T;
  attempt: number;
  ack(): Promise<void>;
  nack(delayMs: number): Promise<void>;
}

const DEDUP_TTL_SECONDS = 6 * 60 * 60;
const MAX_ATTEMPTS = 8;

export class TranscodeConsumer {
  constructor(
    private readonly redis: Redis,
    private readonly transcoder: TranscodeService,
    private readonly log: Logger
  ) {}

  private dedupKey(job: TranscodeJob): string {
    return `transcode:seen:${job.assetId}:${job.renditionProfile}`;
  }

  async handle(msg: QueueMessage<TranscodeJob>): Promise<void> {
    const job = msg.body;
    const key = this.dedupKey(job);

    const claimed = await this.redis.set(key, msg.id, "EX", DEDUP_TTL_SECONDS, "NX");
    if (claimed === null) {
      this.log.info({ assetId: job.assetId, profile: job.renditionProfile }, "duplicate transcode job skipped");
      await msg.ack();
      return;
    }

    try {
      const output = await this.transcoder.run(job);
      await this.transcoder.publishRendition(job.assetId, job.renditionProfile, output);
      await msg.ack();
    } catch (err) {
      this.log.error({ err, assetId: job.assetId, attempt: msg.attempt }, "transcode failed");
      if (msg.attempt >= MAX_ATTEMPTS) {
        await this.transcoder.markFailed(job.assetId, job.renditionProfile);
        await msg.ack();
        return;
      }
      await msg.nack(Math.min(60_000, 1000 * 2 ** msg.attempt));
    }
  }
}

export interface TranscodeJob {
  assetId: string;
  renditionProfile: "1080p" | "720p" | "480p" | "audio";
  sourceUri: string;
  requestedAt: string;
}

export interface RenditionOutput {
  uri: string;
  durationMs: number;
  bytes: number;
}

export interface TranscodeService {
  run(job: TranscodeJob): Promise<RenditionOutput>;
  publishRendition(assetId: string, profile: string, output: RenditionOutput): Promise<void>;
  markFailed(assetId: string, profile: string): Promise<void>;
}

import Redis from "ioredis";
import { TranscodeConsumer } from "./consumer";
import { createTranscoder } from "./ffmpegTranscoder";
import { subscribe } from "./queue";
import { logger } from "./logger";

const redis = new Redis(process.env.REDIS_URL!);
const consumer = new TranscodeConsumer(redis, createTranscoder(), logger);

subscribe("video.transcode.requested", { concurrency: 4 }, (msg) => consumer.handle(msg));

process.on("SIGTERM", async () => {
  logger.info("shutting down transcode worker");
  await redis.quit();
  process.exit(0);
});
